### ✅ Java (Optimal O(n log n))

```java
class ListNode {
    int val;
    ListNode next;

    ListNode(int val) {
        this.val = val;
    }
}

public class LISLinkedList {

    public static int lengthOfLIS(ListNode head) {
        if (head == null) return 0;

        // Step 1: Convert LinkedList -> Array
        int[] arr = new int[10000];
        int n = 0;

        ListNode curr = head;
        while (curr != null) {
            arr[n++] = curr.val;
            curr = curr.next;
        }

        // Step 2: LIS using patience sorting
        int[] tails = new int[n];
        int size = 0;

        for (int i = 0; i < n; i++) {
            int x = arr[i];

            int left = 0, right = size;
            while (left < right) {
                int mid = (left + right) / 2;
                if (tails[mid] < x) left = mid + 1;
                else right = mid;
            }

            tails[left] = x;
            if (left == size) size++;
        }

        return size;
    }

    // Helper to create list
    public static ListNode build(int[] arr) {
        ListNode dummy = new ListNode(0);
        ListNode curr = dummy;
        for (int x : arr) {
            curr.next = new ListNode(x);
            curr = curr.next;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        ListNode head1 = build(new int[]{5, 1, 8, 4, 10, 6});
        System.out.println(lengthOfLIS(head1)); // 4

        ListNode head2 = build(new int[]{9, 7, 5, 3});
        System.out.println(lengthOfLIS(head2)); // 1
    }
}
```

