// Simple Rate Limiter (Token Bucket - basic idea)
class RateLimiter {
    private int capacity = 5;
    private int tokens = 5;
    private long lastRefill = System.currentTimeMillis();

    public synchronized boolean allowRequest() {
        refill();
        if(tokens > 0){
            tokens--;
            return true;
        }
        return false;
    }

    private void refill() {
        long now = System.currentTimeMillis();
        if(now - lastRefill > 1000){
            tokens = capacity;
            lastRefill = now;
        }
    }
}
```

