## 🌐 7. Controller (Putting everything together)

```java id="controller"
@RestController
@RequestMapping("/api")
public class UrlController {

    @Autowired private UrlService service;
    @Autowired private CacheService cache;
    @Autowired private RateLimiterService rateLimiter;

    @PostMapping("/shorten")
    public ResponseEntity<String> shorten(@RequestParam String url,
                                          @RequestHeader String userId){

        if(!rateLimiter.allow(userId)){
            return ResponseEntity.status(429).body("Too many requests");
        }

        String shortUrl = service.createShortUrl(url, Long.parseLong(userId));
        return ResponseEntity.ok(shortUrl);
    }

    @GetMapping("/{shortUrl}")
    public ResponseEntity<Void> redirect(@PathVariable String shortUrl){

        String cached = cache.get(shortUrl);

        if(cached != null){
            return ResponseEntity.status(302)
                    .location(URI.create(cached))
                    .build();
        }

        Url url = service.getByShortUrl(shortUrl);

        cache.cache(shortUrl, url.getOriginalUrl());

        return ResponseEntity.status(302)
                .location(URI.create(url.getOriginalUrl()))
                .build();
    }
}
```

