## ✅ 1️⃣ Using `Semaphore`
```java
import java.util.concurrent.Semaphore;

class ABCSemaphore {

    private final Semaphore a = new Semaphore(1);
    private final Semaphore b = new Semaphore(0);
    private final Semaphore c = new Semaphore(0);

    public void printA() {
        try {
            while (true) {
                a.acquire();
                System.out.print("A");
                b.release();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void printB() {
        try {
            while (true) {
                b.acquire();
                System.out.print("B");
                c.release();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void printC() {
        try {
            while (true) {
                c.acquire();
                System.out.print("C");
                a.release();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
```

