// Valid Parentheses
import java.util.*;

class ValidParentheses {
    public boolean isValid(String s) {
        Stack<Character> st = new Stack<>();

        for(char c : s.toCharArray()) {
            if(c=='(' || c=='{' || c=='[') st.push(c);
            else {
                if(st.isEmpty()) return false;
                char top = st.pop();
                if((c==')' && top!='(') ||
                   (c=='}' && top!='{') ||
                   (c==']' && top!='['))
                    return false;
            }
        }
        return st.isEmpty();
    }
}
