## ✅ Generic Utility (N threads sequence)

```java id="9w6p7a"
import java.util.concurrent.locks.*;

public class OrderedExecutor {

    private final int n;
    private int turn = 0;

    private final Lock lock = new ReentrantLock();
    private final Condition[] conditions;

    public OrderedExecutor(int n) {
        this.n = n;
        this.conditions = new Condition[n];
        for (int i = 0; i < n; i++) {
            conditions[i] = lock.newCondition();
        }
    }

    public void run(int threadId, Runnable task) {
        while (true) {
            lock.lock();
            try {
                while (turn % n != threadId) {
                    conditions[threadId].await();
                }

                task.run();          // actual work
                turn++;

                conditions[(threadId + 1) % n].signal(); // next thread

            } catch (Exception e) {
            } finally {
                lock.unlock();
            }
        }
    }
}
```

