import java.util.concurrent.locks.*;

public class OrderedPrinter {

    private final int n;
    private final int max;
    private int num = 1;

    private final Lock lock = new ReentrantLock();
    private final Condition[] conditions;

    public OrderedPrinter(int n, int max) {
        this.n = n;
        this.max = max;
        this.conditions = new Condition[n];
        for (int i = 0; i < n; i++) {
            conditions[i] = lock.newCondition();
        }
    }

    public void print(int threadId) {
        while (true) {
            lock.lock();
            try {
                while (num <= max && (num - 1) % n != threadId) {
                    conditions[threadId].await();
                }

                if (num > max) {
                    for (Condition c : conditions) c.signalAll();
                    break;
                }

                System.out.print("T" + threadId + ":" + num + " ");
                num++;

                conditions[(threadId + 1) % n].signal();

            } catch (Exception e) {
            } finally {
                lock.unlock();
            }
        }
    }
}
