            try {
                while (true) {
                    int val = queue.take();
                    System.out.println("Consumed: " + val);
                    Thread.sleep(1000);
                }
            } catch (Exception e) {}
        };

        new Thread(producer).start();
        new Thread(consumer).start();
    }
}
