```javascript
// Function to generate PDF with styles
function generatePDF(resume, filePath, styles) {
  const doc = new PDFDocument();

  // Pipe the PDF content to a file
  doc.pipe(fs.createWriteStream(filePath));

  // Helper function to apply styles
  function applyStyles(text, style) {
    if (style.fontSize) doc.fontSize(style.fontSize);
    if (style.font) doc.font(style.font);
    if (style.color) doc.fillColor(style.color);
    if (style.alignment) doc.align(style.alignment);
    if (style.underline) doc.underline(style.underline);
    doc.text(text).moveDown();
  }

  // Write resume content to PDF using styles
  applyStyles(`Resume of ${resume.name}`, styles.title);
  applyStyles(`Email: ${resume.email}`, styles.contactInfo);
  applyStyles(`Phone: ${resume.phone}`, styles.contactInfo);
  applyStyles(`Education: ${resume.education.degree} from ${resume.education.university} (${resume.education.year})`, styles.bodyText);
  applyStyles('Experience:', styles.sectionHeading);
  resume.experience.forEach(exp => {
    applyStyles(`- ${exp.position} at ${exp.company} (${exp.duration})`, styles.bodyText);
  });
  applyStyles('Skills:', styles.sectionHeading);
  resume.skills.forEach(skill => {
    applyStyles(`- ${skill}`, styles.bodyText);
  });

  // Finalize the PDF
  doc.end();
}

// Styles defined as a JSON object
const styles = {
  title: { fontSize: 20, alignment: 'center', font: 'Helvetica-Bold' },
  sectionHeading: { fontSize: 14, underline: true, font: 'Helvetica-Bold' },
  contactInfo: { fontSize: 12, color: 'blue', font: 'Helvetica' },
  bodyText: { fontSize: 12, font: 'Helvetica' }
};

// Generate PDF using styles
generatePDF(resume, 'resume-styled.pdf', styles);
```

In this modified version:

- I added a `applyStyles` helper function within `generatePDF` to apply styles to text.
- Styles are applied based on the provided style object.
- Each text block is passed to `applyStyles` along with the corresponding style object.

