3. **Set Up the Question Model**: Create a folder named `models` and inside it, create a file named `Question.js` to define the question model:

```javascript
let questions = [];
let nextId = 1;

class Question {
  constructor(text, answer, priority) {
    this.id = nextId++;
    this.text = text;
    this.answer = answer;
    this.priority = priority;
  }
}

module.exports = {
  Question,
  questions
};
