4. **Create Endpoints**: Define endpoints for saving, updating, getting all, and getting by ID for questions:

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const { Question, questions } = require('./models/Question');

const app = express();
const PORT = process.env.PORT || 3000;

app.use(bodyParser.json());

// Save a question
app.post('/questions', (req, res) => {
  const { text, answer, priority } = req.body;
  const question = new Question(text, answer, priority);
  questions.push(question);
  res.json(question);
});

// Update a question by ID
app.put('/questions/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const { text, answer, priority } = req.body;
  const question = questions.find(q => q.id === id);
  if (!question) {
    return res.status(404).json({ error: 'Question not found' });
  }
  question.text = text || question.text;
  question.answer = answer || question.answer;
  question.priority = priority || question.priority;
  res.json(question);
});

// Get all questions
app.get('/questions', (req, res) => {
  res.json(questions);
});

// Get a question by ID
app.get('/questions/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const question = questions.find(q => q.id === id);
  if (!question) {
    return res.status(404).json({ error: 'Question not found' });
  }
  res.json(question);
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

With these endpoints, you can now save, update, get all, and get by ID for questions using your Express server. Make sure to test them with a tool like Postman or curl.

