        maps = fillWithChildren(maps, null, ++step);
        log("Received Result: Get List of Map of object, having field, name, uniqueId, level : " +
            maps.stream().map(forLoggingTreeHierarchy).collect(Collectors.toList()), ++step);
    }

    private static Function<LineInfoPojo, String> forLoggingTreeHierarchy = 
        lineInfo -> formatLineInfoPojo(lineInfo, "\t");

    private static String formatLineInfoPojo(LineInfoPojo lineInfo, String prefix) {
        return "\n" + prefix + "name: " + lineInfo.getName() +
               (lineInfo.getChildren() != null && !lineInfo.getChildren().isEmpty() ? 
                   " , children: " + lineInfo.getChildren().stream()
                       .map(ch -> formatLineInfoPojo(ch, prefix + "\t"))
                       .collect(Collectors.joining(", ", "[", "]")) 
                   : "");
    }

    private static List<LineInfoPojo> fillWithChildren(List<LineInfoPojo> maps, String parentId, int step) {
        List<LineInfoPojo> result = maps.stream()
            .filter(m -> Objects.equals(m.getParentId(), parentId))
            .peek(parent -> parent.setChildren(fillWithChildren(maps, parent.getUniqueId(), step)))
            .collect(Collectors.toList());

        return result;
    }

    private static Function<LineInfoPojo, String> forLoggingLineInfoPojo = 
        lineInfo -> "\n{name: " + lineInfo.getName() +
                    " , indentationLevel: " + lineInfo.getIndentationLevel() +
                    " , diffWithPrevious: " + lineInfo.getDiffWithPrevious() +
                    " , relativeLevel: " + lineInfo.getRelativeLevel() +
                    " , level: " + lineInfo.getLevel() +
                    " , parentName: " + lineInfo.getParentName() + "} ";

    private static List<LineInfoPojo> getLevelNameUniqueIdAndChildrenMap(List<LineInfoPojo> maps, int step) {
        log("Validating indentation and setting levels", step);

        int firstDiff = findIndentationDifference(maps);

        for (int x = 1; x < maps.size(); x++) {
            LineInfoPojo prevPojo = maps.get(x - 1);
            LineInfoPojo pojo = maps.get(x);

            int relativeLevel = pojo.getDiffWithPrevious() / firstDiff;
            pojo.setRelativeLevel(relativeLevel);

            if (relativeLevel == 0) {
                pojo.setParentId(prevPojo.getParentId());
                pojo.setParentName(prevPojo.getParentName());
                pojo.setLevel(prevPojo.getLevel());
            } else if (relativeLevel > 0) {
                pojo.setParentId(prevPojo.getUniqueId());
                pojo.setParentName(prevPojo.getName());
                pojo.setLevel(prevPojo.getLevel() + 1);
            } else {
                pojo = findParentForNegativeLevel(pojo, prevPojo, relativeLevel, maps);
            }
        }
        return maps;
    }

    private static int findIndentationDifference(List<LineInfoPojo> maps) {
        OptionalInt firstDiffOpt = IntStream.range(1, maps.size())
            .map(x -> maps.get(x).getIndentationLevel() - maps.get(x - 1).getIndentationLevel())
            .filter(diff -> diff != 0)
            .findFirst();

        int firstDiff = firstDiffOpt.orElseThrow(() ->
            new IllegalArgumentException("No valid indentation difference found"));

        if (firstDiff < 0 || !maps.stream().skip(1)
                .allMatch(m -> (m.getIndentationLevel() - maps.get(maps.indexOf(m) - 1).getIndentationLevel()) % firstDiff == 0)) {
            throw new IllegalArgumentException(
                "Invalid indentation found. Indentation should increment or decrement in multiples of the first difference.");
        }

        maps.forEach(m -> m.setDiffWithPrevious(m.getIndentationLevel() - maps.get(maps.indexOf(m) - 1).getIndentationLevel()));
        return firstDiff;
    }

    private static LineInfoPojo findParentForNegativeLevel(LineInfoPojo pojo, LineInfoPojo prevPojo, int relativeLevel, List<LineInfoPojo> maps) {
        int counter = Math.abs(relativeLevel);
        LineInfoPojo parentPojo = prevPojo;
        while (counter > 0 && parentPojo != null) {
            String parentId = parentPojo.getParentId();
            parentPojo = maps.stream()
                .filter(m -> m.getUniqueId().equals(parentId))
                .findFirst()
                .orElse(null);
            counter--;
        }
        if (parentPojo != null) {
            pojo.setParentId(parentPojo.getParentId());
            pojo.setParentName(parentPojo.getParentName());
            pojo.setLevel(parentPojo.getLevel() + 1);
        } else {
            throw new IllegalArgumentException("Parent not found for object: " + pojo);
        }
        return pojo;
    }

    private static List<LineInfoPojo> getLineTextAndIndentationMap(List<String> nonEmptyLines, int step) {
        log("Validating indentation characters", step);

        char firstIndentationCharacter = nonEmptyLines.stream()
            .flatMapToInt(line -> line.chars())
            .filter(c -> c == ' ' || c == '\t')
            .mapToObj(c -> (char) c)
            .findFirst()
            .orElseThrow(() -> new IllegalArgumentException("No valid indentation character found"));

        List<LineInfoPojo> lineInfoList = nonEmptyLines.stream()
            .map(line -> {
                int indentationLevel = (int) line.chars()
                    .takeWhile(c -> c == firstIndentationCharacter)
                    .count();
                if (line.chars().anyMatch(c -> c != firstIndentationCharacter && c != ' ' && c != '\t')) {
                    throw new IllegalArgumentException("Mixed indentation found in the line: " + line);
                }
                return LineInfoPojo.builder()
                    .name(line.trim())
                    .indentationLevel(indentationLevel)
                    .uniqueId(UUID.randomUUID().toString())
                    .build();
            })
            .collect(Collectors.toList());

        return lineInfoList;
    }

