        <li <% if (file.selected) { %>
          class="selected"<% } %> >
          <a href="/?filename=<%= encodeURIComponent(file.path) %>"
            ><%= file.name %></a
          >
        </li>
        <% }); %>
      </ul>
    </div>
    <div id="right-section">
